05-4|drk.final:
### 1. Relevant Tool/Endpoint
* **Android Tracking SDK**: `initialize(apiKey)` and `AssetTrackingCallBack` interface / `assetTrackingAddCallback(...)`.
* **iOS Tracking SDK**: `AssetTracking.shared.initialize(apiKey:)` and `AssetTrackingCallback` protocol / `AssetTracking.shared.delegate = self`.

---

### 2. How to Call It

#### Android (Kotlin)
1. **Initialize SDK**: Call `initialize("YOUR_API_KEY")`.
2. **Register Callback**: Implement the `AssetTrackingCallBack` interface and call `assetTrackingAddCallback(this)` (remember to call `assetTrackingRemoveCallback(this)` when finished/destroyed).
3. **Handle Updates**: Override `onLocationSuccess(location: Location)` and `onLocationFailure(exception: Exception)`.
4. **Start Tracking**: Call `assetTrackingStart()`.

#### iOS (Swift)
1. **Initialize SDK**: Call `AssetTracking.shared.initialize(apiKey: "YOUR_API_KEY")`.
2. **Register Delegate**: Adopt the `AssetTrackingCallback` protocol and assign `AssetTracking.shared.delegate = self`.
3. **Handle Updates**: Implement `onLocationSuccess(location: CLLocation)` and `onLocationFailure(error: Error)`.
4. **Start Tracking**: Call `AssetTracking.shared.startTracking()`.

---

### 3. Example

#### Android (Kotlin)
```kotlin
import ai.nextbillion.tracking.AssetTrackingCallBack
import ai.nextbillion.tracking.initialize
import ai.nextbillion.tracking.assetTrackingAddCallback
import ai.nextbillion.tracking.assetTrackingRemoveCallback
import ai.nextbillion.tracking.assetTrackingStart
import ai.nextbillion.tracking.assetTrackingStop
import android.location.Location

class TrackingActivity : AppCompatActivity(), AssetTrackingCallBack {

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_tracking)

        // 1. Initialize Asset Tracking SDK
        initialize("PUT_YOUR_API_KEY_HERE")

        // 2. Register for location and tracking callbacks
        assetTrackingAddCallback(this)

        // 3. Start tracking (ensure permissions are granted)
        assetTrackingStart()
    }

    override fun onDestroy() {
        super.onDestroy()
        // Unregister callback and stop tracking
        assetTrackingRemoveCallback(this)
        assetTrackingStop()
    }

    // --- AssetTrackingCallBack implementation ---

    override fun onLocationSuccess(location: Location) {
        val lat = location.latitude
        val lon = location.longitude
        val speed = location.speed
        val accuracy = location.accuracy
        println("Location update: Lat: $lat, Lon: $lon, Speed: $speed, Accuracy: $accuracy")
    }

    override fun onLocationFailure(exception: Exception) {
        println("Location update failed: ${exception.message}")
    }

    override fun onTrackingStart(assetId: String) {
        println("Asset Tracking started for ID: $assetId")
    }

    override fun onTrackingStop(assetId: String, trackingDisableType: TrackingDisableType) {
        println("Asset Tracking stopped for ID: $assetId")
    }
}
```

#### iOS (Swift)
```swift
import UIKit
import CoreLocation
import NBAssetTracking

class TrackingViewController: UIViewController, AssetTrackingCallback {

    override func viewDidLoad() {
        super.viewDidLoad()

        // 1. Initialize Asset Tracking SDK
        AssetTracking.shared.initialize(apiKey: "YOUR_API_KEY")

        // 2. Assign delegate to listen for location updates
        AssetTracking.shared.delegate = self

        // 3. Start tracking
        AssetTracking.shared.startTracking()
    }

    override func viewDidDisappear(_ animated: Bool) {
        super.viewDidDisappear(animated)
        AssetTracking.shared.stopTracking()
    }

    // --- AssetTrackingCallback Protocol Implementation ---

    func onLocationSuccess(location: CLLocation) {
        let lat = location.coordinate.latitude
        let lon = location.coordinate.longitude
        let speed = location.speed
        let accuracy = location.horizontalAccuracy
        print("Location update: Lat: \(lat), Lon: \(lon), Speed: \(speed), Accuracy: \(accuracy)")
    }

    func onLocationFailure(error: Error) {
        print("Failed to get location data: \(error.localizedDescription)")
    }

    func onTrackingStart(assetId: String) {
        print("Asset Tracking started for ID: \(assetId)")
    }

    func onTrackingStop(assetId: String, trackingDisableType: NBAssetTracking.TrackingDisableType) {
        print("Asset Tracking stopped for ID: \(assetId)")
    }

    func onLocationServiceOff() {
        print("Location services are disabled by the user.")
    }
}
```

---

### 4. Source URLs
* **Android**: [NextBillion.ai Android Tracking SDK - Get AssetTrackingCallback](https://docs.nextbillion.ai/tracking/android-tracking-sdk/examples/get-assettracking-callback)
* **iOS**: [NextBillion.ai iOS Tracking SDK - Get AssetTrackingCallback ViewController](https://docs.nextbillion.ai/tracking/ios-tracking-sdk/examples/get-assettracking-callback)

