08-2|drk.final:
### 1. Relevant Tool / Endpoint
* **SDK / Tool:** NextBillion Flutter Navigation SDK (`nb_navigation_flutter`)
* **Classes:** `NavNextBillionMap`, `RouteLineProperties`, and `NBNavigation`

---

### 2. How to Call It
To customize the route line style on the map:
1. Initialize the `NBMap` widget and hook into the `onStyleLoadedCallback`.
2. Instantiate `RouteLineProperties` to configure styling options such as:
   * `routeDefaultColor`: Default color of the primary route line.
   * `routeScale`: Width scaling factor for the primary route line.
   * `alternativeRouteDefaultColor` & `alternativeRouteScale`: Styling for alternative routes.
   * `routeShieldColor` & `alternativeRouteShieldColor`: Route shield icon colors.
   * `originMarkerName` & `destinationMarkerName`: Asset image names for origin/destination markers.
   * `durationSymbolPrimaryBackgroundColor`, `durationSymbolAlternativeBackgroundColor`: Duration badge background colors.
   * `durationSymbolPrimaryTextStyle`, `durationSymbolAlternativeTextStyle`: Badge text styles.
3. Pass `RouteLineProperties` to `NavNextBillionMap.create(controller, routeLineProperties: ...)`.
4. Fetch routes via `NBNavigation.fetchRoute(requestParams)` and render them on the map via `navNextBillionMap.drawRoute(routes)`.

---

### 3. Example
```dart
import 'package:flutter/material.dart';
import 'package:nb_navigation_flutter/nb_navigation_flutter.dart';

class RouteLineStyleExample extends StatefulWidget {
  const RouteLineStyleExample({super.key});

  @override
  State<RouteLineStyleExample> createState() => _RouteLineStyleExampleState();
}

class _RouteLineStyleExampleState extends State<RouteLineStyleExample> {
  NextbillionMapController? controller;
  late NavNextBillionMap navNextBillionMap;

  LatLng origin = const LatLng(1.312533169133601, 103.75986708439264);
  LatLng dest = const LatLng(1.310473772283314, 103.77982271935586);

  void _onMapCreated(NextbillionMapController controller) {
    this.controller = controller;
  }

  void _onStyleLoaded() async {
    if (controller != null) {
      // Define custom route line properties
      var routeLineStyle = const RouteLineProperties(
        routeDefaultColor: Color(0xFFE97F2F),
        routeScale: 1.0,
        alternativeRouteScale: 1.0,
        routeShieldColor: Color(0xFF54E910),
        durationSymbolPrimaryBackgroundColor: Color(0xFFE97F2F),
      );

      // Create NavNextBillionMap with custom line properties
      navNextBillionMap = await NavNextBillionMap.create(
        controller!,
        routeLineProperties: routeLineStyle,
      );
    }
  }

  void _fetchAndDrawRoute() async {
    RouteRequestParams requestParams = RouteRequestParams(
      origin: origin,
      destination: dest,
      mode: ValidModes.car,
    );

    DirectionsRouteResponse response = await NBNavigation.fetchRoute(requestParams);
    if (response.directionsRoutes.isNotEmpty) {
      navNextBillionMap.clearRoute();
      navNextBillionMap.drawRoute(response.directionsRoutes);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text("Customize Route Line Style")),
      body: Stack(
        children: [
          NBMap(
            onMapCreated: _onMapCreated,
            initialCameraPosition: CameraPosition(
              target: LatLng(origin.latitude, 103.76986708439264),
              zoom: 13.0,
            ),
            onStyleLoadedCallback: _onStyleLoaded,
          ),
          Positioned(
            bottom: 40,
            left: 16,
            child: ElevatedButton(
              onPressed: _fetchAndDrawRoute,
              child: const Text("Fetch & Draw Route"),
            ),
          ),
        ],
      ),
    );
  }
}
```

---

